const j = $input.first().json;
const answer = String(j.answer || '');
const sources = String(j.sources || '');
const minChars = Number(j.min_source_chars) || 40;
const sourcesUsable = sources.trim().length >= minChars;
const norm = s => s.toLowerCase().replace(/[\u00a0,]/g, ' ');
const srcNorm = norm(sources);
const unsupported = [];
let hardPoints = 0;
const factPattern = /\d[\d.,]*\s?(%|percent|eur|usd|chf|gbp|days?|hours?|weeks?|months?|years?)?/gi;
const seen = new Set();
for (const m of answer.matchAll(factPattern)) {
  const raw = m[0].trim();
  const token = raw.replace(/[.,]$/, '');
  const numberPart = (token.match(/\d[\d.]*/) || [''])[0];
  if (!numberPart || seen.has(token.toLowerCase())) continue;
  seen.add(token.toLowerCase());
  if (!srcNorm.includes(numberPart.toLowerCase())) {
    unsupported.push(token);
    hardPoints += 30;
  }
}
const urls = answer.match(/https?:\/\/[^\s)]+/g) || [];
for (const u of urls) {
  if (!sources.includes(u)) { unsupported.push(u); hardPoints += 20; }
}
return [{ json: {
  entry: String(j.entry || 'subworkflow'),
  answer: answer,
  sources: sources,
  sources_usable: sourcesUsable ? 'yes' : 'no',
  sources_chars: sources.trim().length,
  unsupported_facts: unsupported,
  hard_points: Math.min(100, hardPoints),
  block_at: Number(j.block_at) || 60,
  review_at: Number(j.review_at) || 25,
  model_max_points: Number(j.model_max_points) || 40
} }];

