parameters.jsCode:
const det = $('Run Deterministic Fact Checks').first().json;
const first = $input.first();
const raw = first ? first.json : {};
const src = raw && typeof raw.output === 'object' && raw.output !== null ? raw.output : raw;
let note = 'Groq compared every claim against the sources.';
let conf = Number(src ? src.confidence : NaN);
if (!Number.isFinite(conf)) { conf = 0; note = 'The model did not return a readable judgement; this verdict rests on the deterministic checks alone.'; }
if (conf > 0 && conf <= 1) { conf = Math.round(conf * 100); }
conf = Math.max(0, Math.min(100, Math.round(conf)));
let modelClaims = [];
if (src && Array.isArray(src.unsupported_claims)) { modelClaims = src.unsupported_claims.filter(c => c && c.claim); }
const cap = Number.isFinite(Number(det.model_max_points)) ? Number(det.model_max_points) : 40;
const modelPoints = Math.min(cap, Math.round(modelClaims.length * 15 * (conf / 100)));
const score = Math.min(100, (Number(det.hard_points) || 0) + modelPoints);
let verdict = 'PASS';
let refusal = '';
if (det.sources_usable !== 'yes') {
  verdict = 'REVIEW';
  refusal = 'The sources are missing or too short to check against, so nothing was actually verified. This gate refuses to PASS an answer it could not check.';
} else if (score >= (Number(det.block_at) || 60)) {
  verdict = 'BLOCK';
} else if (score >= (Number(det.review_at) || 25)) {
  verdict = 'REVIEW';
}
const lines = [];
for (const f of (det.unsupported_facts || [])) { lines.push('fact not in sources: "' + f + '"'); }
for (const c of modelClaims) { lines.push('claim not supported: "' + String(c.claim).slice(0, 140) + '" (' + String(c.reason || '').slice(0, 140) + ')'); }
const reasons = lines.length ? lines.join('\n') : 'Every checked fact and claim was found in the sources.';
return [{ json: {
  entry: det.entry,
  checked_at: new Date().toISOString(),
  verdict: verdict,
  risk_score: score,
  unsupported_facts: (det.unsupported_facts || []).join('; '),
  model_unsupported: modelClaims.map(c => String(c.claim).slice(0, 100)).join('; '),
  model_confidence: conf,
  block_at: Number(det.block_at) || 60,
  review_at: Number(det.review_at) || 25,
  answer_excerpt: String(det.answer).slice(0, 300),
  sources_chars: Number(det.sources_chars) || 0,
  reasons: reasons,
  note: note + (refusal ? ' ' + refusal : '')
} }];

